import{_ as i,o as e,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const B=JSON.parse('{"title":"2018-FEB-22 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-FEB-22 :: Ceph Performance Weekly","date":"2018-02-26T00:00:00.000Z","updated":"2018-02-27T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","蓝存储","RocksDB","缓存","优化","故障转移"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-FEB-22_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-FEB-22_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),t={name:"posts/2018/2018-FEB-22_-_-_Ceph_Performance_Weekly.md"};function s(a,l,n,_,u,p){return e(),o("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Peter, Mark, Assaf, David, John, Josh 等</p><p><strong>会议主题</strong>： Ceph分布式存储性能优化与问题解决</p><p><strong>关键细节</strong>：</p><ul><li><strong>性能优化</strong>： <ul><li>Peter修复了OP Tracker缓慢的问题，显著提升了性能。</li><li>Mark对标记压缩进行了优化，提高了插入和删除效率。</li><li>Assaf对RBD进行了优化，避免了不必要的内存分配。</li><li>John对PG日志进行了优化，提升了性能。</li><li>David解决了与流调试相关的性能问题。</li><li>Josh对个人对象恢复进行了优化。</li></ul></li><li><strong>问题解决</strong>： <ul><li>Peter通过减少缓存修剪频率，提高了性能。</li><li>Mark优化了BlueStore缓存，减少了内存占用。</li><li>Mark对BlueStore进行了重构，简化了代码结构。</li><li>Peter合并了配置归一化检查和配置选项观察者。</li><li>Assaf优化了对象映射，提高了性能。</li><li>John对BlueStore后端进行了更新。</li><li>Josh对BlueStore缓存进行了优化。</li></ul></li><li><strong>讨论议题</strong>： <ul><li><strong>BlueStore缓存</strong>： <ul><li>讨论了BlueStore缓存存在的复杂性和性能问题，考虑移除BlueStore缓存，仅使用RocksDB缓存进行元数据存储。</li><li>认为需要更多数据来了解RocksDB缓存中Bloom过滤器的大小和内存占用。</li><li>讨论了禁用PG元项的Bloom过滤器，并部署测试集群来获取数据。</li></ul></li><li><strong>缓存配置</strong>： <ul><li>讨论了缓存配置的复杂性和用户理解难度，认为应该简化缓存配置，并提供一个用户友好的设置。</li><li>认为可以尝试使用简单的启发式方法或更复杂的在线优化模型。</li></ul></li><li><strong>其他</strong>： <ul><li>讨论了FIO瓶颈和异步消息传递的性能问题。</li><li>讨论了编码/解码和CRC计算的优化。</li></ul></li></ul></li><li><strong>决定的事项</strong>： <ul><li>继续测试和优化OP Tracker性能。</li><li>继续优化标记压缩和BlueStore缓存。</li><li>继续优化对象映射。</li><li>继续优化PG日志。</li><li>继续优化个人对象恢复。</li><li>讨论BlueStore缓存的移除和RocksDB缓存的优化。</li><li>讨论缓存配置的简化。</li><li>讨论FIO瓶颈和异步消息传递的性能优化。</li><li>收集更多数据来了解RocksDB缓存中Bloom过滤器的大小和内存占用。</li></ul></li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Peter将测试和优化OP Tracker性能。</li><li>Mark将测试和优化标记压缩和BlueStore缓存。</li><li>Assaf将测试和优化对象映射。</li><li>John将测试和优化PG日志。</li><li>Josh将测试和优化个人对象恢复。</li><li>讨论BlueStore缓存的移除和RocksDB缓存的优化。</li><li>讨论缓存配置的简化。</li><li>讨论FIO瓶颈和异步消息传递的性能优化。</li><li>收集更多数据来了解RocksDB缓存中Bloom过滤器的大小和内存占用。</li></ul>',8)])])}const g=i(t,[["render",s]]);export{B as __pageData,g as default};
